function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'RangeModule' || args[0].length !== 0) return 'Start with RangeModule and no arguments.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls after the constructor.';
  const names = ['addRange', 'queryRange', 'removeRange'];
  for (let i = 1; i < operations.length; i++) {
    if (!names.includes(operations[i])) return 'Only addRange, queryRange and removeRange can follow the constructor.';
    const [left, right] = args[i];
    if (args[i].length !== 2 || !Number.isInteger(left) || !Number.isInteger(right)) return 'Each call takes two whole numbers, left and right.';
    if (left < 1 || left >= right || right > 1000000000) return 'Each call needs 1 <= left < right <= 10^9.';
  }
  return null;
}

