class RangeModule {
  constructor() {
    this.intervals = [];
  }

  // Index of the first stored interval whose end is >= x.
  firstEndAtLeast(x) {
    let low = 0;
    let high = this.intervals.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (this.intervals[mid][1] < x) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  }

  addRange(left, right) {
    const start = this.firstEndAtLeast(left);
    let end = start;
    let low = left;
    let high = right;
    while (end < this.intervals.length && this.intervals[end][0] <= right) {
      low = Math.min(low, this.intervals[end][0]);
      high = Math.max(high, this.intervals[end][1]);
      end++;
    }
    this.intervals.splice(start, end - start, [low, high]);
  }

  queryRange(left, right) {
    const index = this.firstEndAtLeast(right);
    return index < this.intervals.length && this.intervals[index][0] <= left;
  }

  removeRange(left, right) {
    const start = this.firstEndAtLeast(left);
    let end = start;
    const pieces = [];
    while (end < this.intervals.length && this.intervals[end][0] < right) {
      const [low, high] = this.intervals[end];
      if (low < left) {
        pieces.push([low, left]);
      }
      if (high > right) {
        pieces.push([right, high]);
      }
      end++;
    }
    this.intervals.splice(start, end - start, ...pieces);
  }
}

