class RangeModule {
  // Every endpoint ever seen splits the line into segments; on[i] says whether [points[i], points[i + 1]) is tracked.
  constructor() {
    this.points = [];
    this.on = [];
  }
  cut(x) {
    let i = 0;
    while (i < this.points.length && this.points[i] < x) i++;
    if (this.points[i] !== x) {
      this.points.splice(i, 0, x);
      this.on.splice(i, 0, i > 0 ? this.on[i - 1] : false);
    }
    return i;
  }
  paint(left, right, value) {
    const a = this.cut(left);
    const b = this.cut(right);
    for (let j = a; j < b; j++) this.on[j] = value;
  }
  addRange(left, right) {
    this.paint(left, right, true);
  }
  removeRange(left, right) {
    this.paint(left, right, false);
  }
  queryRange(left, right) {
    const a = this.cut(left);
    const b = this.cut(right);
    for (let j = a; j < b; j++) if (!this.on[j]) return false;
    return true;
  }
}

