function generate(rand, size) {
  const operations = ['RangeModule'];
  const args = [[]];
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 15);
  const limit = size === 'large' ? (rand() < 0.5 ? 1000000000 : 5000) : (rand() < 0.8 ? 12 : 1000000000);
  const width = size === 'large' ? Math.max(2, Math.floor(limit / (5 + rand() * 40))) : limit;
  const range = () => {
    const left = 1 + Math.floor(rand() * (limit - 1));
    const right = Math.min(limit, left + 1 + Math.floor(rand() * width));
    return [left, right];
  };
  const added = [];
  const addRate = 0.25 + rand() * 0.3;
  const removeRate = 0.1 + rand() * 0.25;
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < addRate) {
      const pair = range();
      added.push(pair);
      operations.push('addRange');
      args.push(pair);
    } else if (roll < addRate + removeRate) {
      operations.push('removeRange');
      args.push(range());
    } else {
      let pair = range();
      if (added.length > 0 && rand() < 0.6) {
        const [a, b] = added[Math.floor(rand() * added.length)];
        const left = a + Math.floor(rand() * (b - a));
        const right = left + 1 + Math.floor(rand() * (b - left));
        pair = [left, right];
      }
      operations.push('queryRange');
      args.push(pair);
    }
  }
  return [operations, args];
}
